import type { Express } from "express";
import { Prisma, type PrismaClient } from "@prisma/client";
import type { AuthLocals } from "./authorization.js";
import { sendError } from "./errors.js";
import { findRequest } from "./requestActions.js";

// Submitting a request and viewing your own requests (F-03 contract). The requester is always the signed-in user;
// the number is generated by the database; nothing the client says about identity or status is read.

const TITLE_MAX = 120;
const DESCRIPTION_MAX = 2000;
const AMOUNT_MAX_CENTS = 100_000_000n; // 1,000,000.00 THB
const MAX_INT4 = 2_147_483_647;

const AMOUNT_FORMAT = "Enter the amount as a number, for example 1250.50.";
const CHOOSE_ACTIVE = "Choose an active reviewer.";
const SELF_REVIEWER = "You cannot be the reviewer of your own request.";
const NOT_RETURNED = "Only a returned request can be resubmitted.";

interface Content {
  title: string;
  description: string;
  amount: string;
}

interface Submission extends Content {
  assignedReviewerId: number;
}

const asObject = (body: unknown) =>
  (typeof body === "object" && body !== null && !Array.isArray(body) ? body : {}) as Record<string, unknown>;

// F-03 §1.4: the content of a request, for a submission and for a resubmission (F-06). Text is stored trimmed.
function readContent(input: Record<string, unknown>, fields: Record<string, string>): Content {
  const title = typeof input.title === "string" ? input.title.trim() : "";
  if (title === "") fields.title = "Enter a title.";
  else if ([...title].length > TITLE_MAX) fields.title = "Title must be 120 characters or fewer.";

  const description = typeof input.description === "string" ? input.description.trim() : "";
  if (description === "") fields.description = "Enter a description.";
  else if ([...description].length > DESCRIPTION_MAX) fields.description = "Description must be 2,000 characters or fewer.";

  const amount = input.amount;
  if (amount === undefined || amount === null || amount === "") {
    fields.amount = "Enter an amount.";
  } else if (typeof amount !== "string" || !/^\d{1,7}(\.\d{1,2})?$/.test(amount)) {
    fields.amount = AMOUNT_FORMAT;
  } else {
    const [whole, fraction = ""] = amount.split(".");
    const cents = BigInt(whole) * 100n + BigInt(fraction.padEnd(2, "0"));
    if (cents <= 0n) fields.amount = "Enter an amount greater than 0.";
    else if (cents > AMOUNT_MAX_CENTS) fields.amount = "Enter an amount of at most 1,000,000.00 THB.";
  }

  return { title, description, amount: amount as string };
}

// F-03 §1.4. Every problem is reported at once.
function parseSubmission(body: unknown): { ok: true; value: Submission } | { ok: false; fields: Record<string, string> } {
  const input = asObject(body);
  const fields: Record<string, string> = {};
  const content = readContent(input, fields);

  const reviewer = input.assignedReviewerId;
  if (typeof reviewer !== "number" || !Number.isInteger(reviewer) || reviewer < 1 || reviewer > MAX_INT4) {
    fields.assignedReviewerId = "Choose a reviewer.";
  }

  if (Object.keys(fields).length > 0) return { ok: false, fields };
  return { ok: true, value: { ...content, assignedReviewerId: reviewer as number } };
}

const person = { select: { id: true, name: true } } as const;
const detailInclude = {
  requester: person,
  assignedReviewer: person,
  decidedBy: person,
  events: { orderBy: [{ createdAt: "asc" }, { id: "asc" }], include: { actor: person } },
} satisfies Prisma.ApprovalRequestInclude;

type DetailRow = Prisma.ApprovalRequestGetPayload<{ include: typeof detailInclude }>;

// The shape of F-03 §2.2. The amount is always a string with two decimals, and only the people the request is about
// appear in it: never an email or a hash.
export function toDetail(row: DetailRow) {
  return {
    id: row.id,
    requestNumber: row.requestNumber,
    title: row.title,
    description: row.description,
    amount: row.amount.toFixed(2),
    status: row.status,
    requester: row.requester,
    assignedReviewer: row.assignedReviewer,
    decidedBy: row.decidedBy,
    decisionCategory: row.decisionCategory,
    decisionReason: row.decisionReason,
    decidedAt: row.decidedAt?.toISOString() ?? null,
    revision: row.revision,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
    history: row.events.map((event) => ({
      id: event.id,
      type: event.type,
      fromStatus: event.fromStatus,
      toStatus: event.toStatus,
      actor: event.actor,
      reason: event.reason,
      category: event.category,
      createdAt: event.createdAt.toISOString(),
    })),
  };
}

export { detailInclude };

export function registerRequestRoutes(app: Express, { prisma }: { prisma: PrismaClient }): void {
  const me = (locals: unknown) => (locals as AuthLocals).auth!.user;

  // The reviewers a request can be assigned to: active, not the caller, sorted by name.
  app.get("/api/reviewers", async (_req, res, next) => {
    try {
      const reviewers = await prisma.user.findMany({
        where: { role: "REVIEWER", isActive: true, id: { not: me(res.locals).id } },
        orderBy: { name: "asc" },
        select: { id: true, name: true },
      });
      res.json({ reviewers });
    } catch (error) {
      next(error);
    }
  });

  app.post("/api/requests", async (req, res, next) => {
    try {
      const parsed = parseSubmission(req.body);
      if (!parsed.ok) return sendError(res, 400, "VALIDATION_ERROR", "Some fields need attention.", parsed.fields);
      const { value } = parsed;
      const user = me(res.locals);

      // The reviewer check and the insert share one transaction. The requester is the session user, whatever the
      // body says; the number and the status come from the database defaults.
      const outcome = await prisma.$transaction(async (tx): Promise<{ error: string } | { created: DetailRow }> => {
        if (value.assignedReviewerId === user.id) return { error: SELF_REVIEWER };
        const reviewer = await tx.user.findFirst({
          where: { id: value.assignedReviewerId, role: "REVIEWER", isActive: true },
          select: { id: true },
        });
        if (!reviewer) return { error: CHOOSE_ACTIVE };

        const created = await tx.approvalRequest.create({
          data: {
            requesterId: user.id,
            assignedReviewerId: reviewer.id,
            title: value.title,
            description: value.description,
            amount: value.amount,
            events: { create: { type: "SUBMITTED", fromStatus: null, toStatus: "SUBMITTED", actorId: user.id } },
          },
          include: detailInclude,
        });
        return { created };
      });

      if ("error" in outcome) {
        return sendError(res, 400, "VALIDATION_ERROR", "Some fields need attention.", { assignedReviewerId: outcome.error });
      }
      res.status(201).json({ request: toDetail(outcome.created) });
    } catch (error) {
      next(error);
    }
  });

  // F-06 section 1.2: the requester edits a RETURNED request and sends it back to the same reviewer.
  app.post("/api/requests/:id/resubmission", async (req, res, next) => {
    try {
      const user = me(res.locals);
      const found = await findRequest(prisma, req.params.id);
      if (!found) return sendError(res, 404, "NOT_FOUND", "Not found.");
      // Only the requester. The assigned reviewer knows the request, so is told why; anyone else learns nothing.
      if (found.requesterId !== user.id) {
        return found.assignedReviewerId === user.id
          ? sendError(res, 403, "NOT_REQUESTER", "Only the requester can resubmit this request.")
          : sendError(res, 404, "NOT_FOUND", "Not found.");
      }

      const fields: Record<string, string> = {};
      const content = readContent(asObject(req.body), fields);
      if (Object.keys(fields).length > 0) {
        return sendError(res, 400, "VALIDATION_ERROR", "Some fields need attention.", fields);
      }
      if (found.status !== "RETURNED") return sendError(res, 409, "INVALID_TRANSITION", NOT_RETURNED);

      // The UPDATE matches only while the request is still RETURNED (BR-14). The number and the reviewer are not
      // written (BR-16), and the new revision makes older screens of the reviewer stale.
      const { id } = found;
      const now = new Date();
      const resubmitted = await prisma.$transaction(async (tx) => {
        const changed = await tx.approvalRequest.updateMany({
          where: { id, status: "RETURNED", requesterId: user.id },
          data: {
            ...content,
            status: "SUBMITTED",
            decidedById: null,
            decidedAt: null,
            decisionReason: null,
            decisionCategory: null,
            revision: { increment: 1 },
            updatedAt: now,
          },
        });
        if (changed.count === 0) return null;

        await tx.requestEvent.create({
          data: {
            requestId: id,
            actorId: user.id,
            type: "RESUBMITTED",
            fromStatus: "RETURNED",
            toStatus: "SUBMITTED",
            createdAt: now,
          },
        });
        return tx.approvalRequest.findUniqueOrThrow({ where: { id }, include: detailInclude });
      });

      if (!resubmitted) return sendError(res, 409, "INVALID_TRANSITION", NOT_RETURNED);
      res.json({ request: toDetail(resubmitted) });
    } catch (error) {
      next(error);
    }
  });

  // Before /api/requests/:id, so "mine" is not read as an id.
  app.get("/api/requests/mine", async (_req, res, next) => {
    try {
      const rows = await prisma.approvalRequest.findMany({
        where: { requesterId: me(res.locals).id },
        orderBy: [{ createdAt: "desc" }, { id: "desc" }],
        include: { assignedReviewer: person },
      });
      res.json({
        requests: rows.map((row) => ({
          id: row.id,
          requestNumber: row.requestNumber,
          title: row.title,
          amount: row.amount.toFixed(2),
          status: row.status,
          assignedReviewer: row.assignedReviewer,
          createdAt: row.createdAt.toISOString(),
        })),
      });
    } catch (error) {
      next(error);
    }
  });

  // Visible only to the requester and the assigned reviewer. Everything else (another user's request, a missing id,
  // an id that is not a number) is the same 404, so existence is never revealed (BR-08).
  app.get("/api/requests/:id", async (req, res, next) => {
    try {
      const id = /^[1-9]\d*$/.test(req.params.id) ? Number(req.params.id) : NaN;
      const user = me(res.locals);
      const row =
        Number.isSafeInteger(id) && id <= MAX_INT4
          ? await prisma.approvalRequest.findFirst({
              where: { id, OR: [{ requesterId: user.id }, { assignedReviewerId: user.id }] },
              include: detailInclude,
            })
          : null;
      if (!row) return sendError(res, 404, "NOT_FOUND", "Not found.");
      res.json({ request: toDetail(row) });
    } catch (error) {
      next(error);
    }
  });
}
